head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

//화면ID
scwin.vScrenID = "ULDSTF08021.xml";
scwin.pQtyApplDtlID = "ULDSTF08022";
scwin.pQtyIsurDtlID = "ULDSTF08023";
scwin.pIsuNmChgApplDtlID = "ULDSTF08025";
scwin.pIsuNmChgDtlID = "ULDSTF08026";

//팝업에서 사용될 변수
scwin.fr_SecuGrpId = SECUGRP_ID_EN;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.clickBzProcsNo = "";
scwin.clickIsuCd = "";
scwin.clickAcptNo = "";
scwin.clickDisclsYn = "";

//수량변경 변수
scwin.vQtyApplKind = ""; //수량변경: 신청내역 팝업구분(신규:N, 수정:U)
scwin.vQtyIsurKind = ""; //수량변경: 발행 및 상장내역(수량변경)  팝업 구분(신규:N, 수정:U)
scwin.v_QtyApplKey = "";
scwin.v_UpdQtyApplParam = new Array(); //팝업에서 사용(수량변경 신청내역)
scwin.v_UpdQtyIsurParam = new Array(); //팝업에서 사용(수량변경 발행내역)
scwin.v_QtyApplRowClicked = false;

//종목명변경 변수
scwin.vIsuNmChgApplKind = ""; //종목명변경: 신청내역 팝업구분(신규:N, 수정:U)
scwin.vIsuNmChgKind = ""; //종목명변경: 종목명변경 상장내역 팝업 구분(신규:N, 수정:U)
scwin.v_UpdItmApplParam = new Array(); //팝업에서 사용(수량변경 신청내역)
scwin.v_UpdItmIsurParam = new Array(); //팝업에서 사용(수량변경 발행내역)

//그리드 조회된 결과없습니다. 메세지 show/hide 용 위한 변수
scwin.vTotalCountGrid1 = 0;
scwin.vTotalCountGrid2 = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
* 함수명 : fn_list_qty_appl(isurCd, isuCd) {
* 설명    : 수량변경의 신청내역조회
               isurCd: 발행기관코드, isuCd:종목코드
***********************************************/
scwin.fn_list_qty_appl = function(isurCd, isuCd) {
    //검색조건 타지 않도록 함.
    isurCd = "";
    isuCd = "";

    //	1. 수량변경 신청내역 조회	
    var url = "/etn/EtnChgList.do?method=selectQtyApplDtlList";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + isurCd;
    url += "&SRCH_ISU_CD=" + isuCd;
    dts_Qty_ApplDtl.DataID = encodeURI(url);
    dts_Qty_ApplDtl.Reset();
    //ShowWin(grd_Qty_ApplDtl); 

};



/********************************************** 
 * 함수명 : fn_list_sync()
 * 설명    :  수량변경의 발행(추가상장, 중도상환) 및 상장내역 조회
 ***********************************************/
scwin.fn_list_sync = function() {
    //종목코드가 없을경우 미처리
    if ($c.ut.trim($c.stf.getObjectValue(txb_SearchIsuCd)) == "") {
        dts_Qty_IsurDtl.removeAll();
        return;
    }

    // 발행 및 상장 내역 조회	
    var url = "/etn/EtnChgList.do?method=selectQtyIsurDtlList";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
    url += "&SRCH_ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd);
    dts_Qty_IsurDtl.DataID = encodeURI(url);
    dts_Qty_IsurDtl.Reset();
    //ShowWin(grd_Qty_IsurDtl);

    //'Loading...' 메세지숨김
    //fn_CloseLoadingImg();

    //'조회된결과없습니다' 메세지숨김 (그리드 2개중 하나라도 데이터 0개 이면)
    if (scwin.vTotalCountGrid1 == 0 && scwin.vTotalCountGrid2 == 0) {
        $c.cm.ShowNoData(grd_Qty_IsurDtl);
        //fn_CloseNoData();

    } else {
        $c.lce.fn_CloseNoData();
    }
};



/********************************************** 
 * 함수명 : fn_list_chglist_appl()
 * 설명    : 종목명변경의 신청내역 조회
 ***********************************************/
scwin.fn_list_chglist_appl = function(isurCd, isuCd) {
    //검색조건 타지 않도록 함.
    isurCd = "";
    isuCd = "";

    /*	1. 종목명변경 신청내역 조회	*/
    var url = "/etn/EtnChgList.do?method=selectIsuNmChgApplDtlList";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + isurCd;
    url += "&SRCH_ISU_CD=" + isuCd;
    dts_Itm_ApplDtl.DataID = encodeURI(url);
    dts_Itm_ApplDtl.Reset();
};


/********************************************** 
 * 함수명 : fn_list_chglist_sync()
 * 설명    : 종목명변경의 종목명 변경상장 내역 조회
 ***********************************************/
scwin.fn_list_chglist_sync = function() {
    //종목코드가 없을경우 미처리
    if ($c.ut.trim($c.stf.getObjectValue(txb_SearchIsuCd2)) == "") {
        dts_Itm_IsurDtl.removeAll();
        return;
    }

    //발행 및 상장 내역 조회
    var url = "/etn/EtnChgList.do?method=selectIsuNmChgDtlList";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD2);
    url += "&SRCH_ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd2);
    dts_Itm_IsurDtl.DataID = encodeURI(url);
    dts_Itm_IsurDtl.Reset();
    //ShowWin(grd_Itm_ListDtl);

    //'Loading...' 메세지숨김
    //fn_CloseLoadingImg();

    //'조회된결과없습니다' 메세지숨김 (그리드 2개중 하나라도 데이터 0개 이면)
    if (scwin.vTotalCountGrid1 > 0 || scwin.vTotalCountGrid2 > 0) {
        $c.lce.fn_CloseNoData();
    } else {
        $c.cm.ShowNoData(grd_Itm_ListDtl);
    }
};



/********************************************** 
 * 함수명 : fn_set_code()
 * 설명    : Calling 공통코드 in onload Form Event
 ***********************************************/
scwin.fn_set_code = function() {
    //발행기관조회(수량변경)
    dts_EtnInst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_EtnInst.Reset();

    //종목명변경의 탭에 있는 발행기관 DataSet copy (dts_EtnIsnt에 syncload=true로 설정해야 함)
    //....종목명변경의 탭에 있는 발행기관 change event를 OnSelChange2()로 변경함.
    $c.stf.CopyDataSet(dts_EtnInst, dts_EtnInst2);
    cmb_ISUR_CD2.setSelectedIndex(0);
};


/********************************************** 
 * 함수명 : fn_GetParIsur(), fn_SetParIsur()
 * 설명    : 상장신청 발행기관 호출관련
 ***********************************************/
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (MaxTab_01.getSelectedTabIndex() == "1") {
        arrPar[0] = $c.stf.getObjectValue(txb_SearchIsuCd); // 코드값을 포함할 컨트롤
        arrPar[1] = $c.stf.getObjectValue(txb_SearchIsuNm); // 명칭값을 포함할 컨트롤

    } else {
        arrPar[0] = $c.stf.getObjectValue(txb_SearchIsuCd2); // 코드값을 포함할 컨트롤
        arrPar[1] = $c.stf.getObjectValue(txb_SearchIsuNm2); // 명칭값을 포함할 컨트롤

    }
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        if (MaxTab_01.getSelectedTabIndex() == "1") {
            txb_SearchIsuCd.setValue(arrPar[0].ISU_CD);
            txb_SearchIsuNm.setValue(arrPar[0].ISU_KOR_ABBRV);
            $c.stf.setObjectValue(cmb_ISUR_CD, arrPar[0].ISUR_CD);
        } else {
            txb_SearchIsuCd2.setValue(arrPar[0].ISU_CD);
            txb_SearchIsuNm2.setValue(arrPar[0].ISU_KOR_ABBRV);
            $c.stf.setObjectValue(cmb_ISUR_CD2, arrPar[0].ISUR_CD);
        }
    }
};




/********************************************** 
 * 함수명 : fn_PopQtyAppl(kind)
 * Param  : kind (N:신규, A:조회)
 * 설명    : 수량변경 >  신청내역(중도상환) > 팝업
 ***********************************************/
scwin.fn_PopQtyAppl = async function(kind, rowno, colid) {
    //신규저장, 수정 구분
    scwin.vQtyApplKind = kind;

    //신규 (신청내역)
    var i = 0;
    scwin.clickAcptNo = dts_Qty_ApplDtl.getCellData(rowno, "ACPT_NO");
    scwin.v_UpdQtyApplParam[i++] = dts_Qty_ApplDtl.getCellData(rowno, "ISU_CD");
    scwin.v_UpdQtyApplParam[i++] = dts_Qty_ApplDtl.getCellData(rowno, "ISUR_CD");
    await $c.frame.CreateDialogFrame(scwin.pQtyApplDtlID, "../etn/" + scwin.pQtyApplDtlID + ".gfm", "수량변경 신청내역 세부내역", 20, 00, 720, 260, "window");
};


/********************************************** 
 * 함수명 : fn_PopQtyIsur(kind)
 * Param  : kind (N:신규, A:조회)
 * 설명    : 수량변경 > 발행 및 상장내역 > 팝업
 ***********************************************/
scwin.fn_PopQtyIsur = async function(kind, rowno, colid) {
    //신규저장, 수정 구분
    scwin.vQtyIsurKind = kind;
    if (kind == "N") {
        await $c.frame.CreateDialogFrame(scwin.pQtyIsurDtlID, "../etn/" + scwin.pQtyIsurDtlID + ".gfm", "수량변경 발행 및 상장내역 신규", 20, 00, 720, 260, "window");
    } else if (kind == "U") {
        //업무처리번호
        var i = 0;
        scwin.v_UpdQtyIsurParam[i++] = dts_Qty_IsurDtl.getCellData(rowno, "BZ_PROCS_NO");
        scwin.v_UpdQtyIsurParam[i++] = dts_Qty_IsurDtl.getCellData(rowno, "ISUR_CD");
        scwin.v_UpdQtyIsurParam[i++] = dts_Qty_IsurDtl.getCellData(rowno, "DISCLS_YN");
        scwin.v_UpdQtyIsurParam[i++] = dts_Qty_IsurDtl.getCellData(rowno, "LIST_BZ_TP_CD");
        await $c.frame.CreateDialogFrame(scwin.pQtyIsurDtlID, "../etn/" + scwin.pQtyIsurDtlID + ".gfm", "수량변경 발행 및 상장내역 세부내역", 20, 00, 720, 260, "window");
    }
};



/********************************************** 
 * 함수명 : fn_PopIsuNmAppl(kind)
 * Param  : kind (N:신규, A:조회)
 * 설명    : 종목명변경  > 신청내역 > 팝업
 ***********************************************/
scwin.fn_PopIsuNmAppl = async function(kind, rowno, colid) {
    //신규저장, 수정 구분
    scwin.vIsuNmChgApplKind = kind;
    scwin.clickBzProcsNo = dts_Itm_ApplDtl.getCellData(rowno, "BZ_PROCS_NO");
    scwin.clickIsuCd = dts_Itm_ApplDtl.getCellData(rowno, "ISU_CD");
    scwin.clickAcptNo = dts_Itm_ApplDtl.getCellData(rowno, "ACPT_NO");
    await $c.frame.CreateDialogFrame(scwin.pIsuNmChgApplDtlID, "../etn/" + scwin.pIsuNmChgApplDtlID + ".gfm", "변경상장 신청 세부내역", 20, 00, 1000, 360, "window");
};


/********************************************** 
 * 함수명 : fn_PopIsuNmChg(kind)
 * Param  : kind (N:신규, U:수정)
 * 설명    : 종목명변경  > 종목명변경 상장내역 > 팝업
 ***********************************************/
scwin.fn_PopIsuNmChg = async function(kind, rowno, colid) {
    //신규저장, 수정 구분
    scwin.vIsuNmChgKind = kind;
    if (kind == "N") {
        //row data of grid
        scwin.clickBzProcsNo = "";
        scwin.clickIsuCd = dts_Itm_IsurDtl.getCellData(rowno, "ISU_CD");
        scwin.clickAcptNo = "";
    } else if (kind == "U") {
        //data of textcontrol
        scwin.clickBzProcsNo = dts_Itm_IsurDtl.getCellData(rowno, "BZ_PROCS_NO");
        scwin.clickIsuCd = dts_Itm_IsurDtl.getCellData(rowno, "ISU_CD");
        scwin.clickAcptNo = dts_Itm_IsurDtl.getCellData(rowno, "ACPT_NO");
        scwin.clickDisclsYn = dts_Itm_IsurDtl.getCellData(rowno, "DISCLS_YN");
    }
    await $c.frame.CreateDialogFrame(scwin.pIsuNmChgDtlID, "../etn/" + scwin.pIsuNmChgDtlID + ".gfm", "변경상장 세부내역", 20, 00, 1000, 360, "window");
};
scwin.btn_Search_onclick = function() {
    $c.lce.fn_CloseNoData();

    //조회버튼 클릭(수량변경)
    if ($c.ut.trim(txb_SearchIsuCd.getValue()) == "") {
        txb_SearchIsuCd.setValue("");
        txb_SearchIsuNm.setValue("");
    }
    scwin.fn_list_qty_appl($c.stf.getObjectValue(cmb_ISUR_CD), $c.stf.getObjectValue(txb_SearchIsuCd));
    scwin.fn_list_sync();
};
scwin.btn_SearchItm_onclick = function() {
    $c.lce.fn_CloseNoData();

    //조회버튼 클릭(종목명변경)
    if ($c.ut.trim(txb_SearchIsuCd2.getValue()) == "") {
        txb_SearchIsuCd2.setValue("");
        txb_SearchIsuNm2.setValue("");
    }
    scwin.fn_list_chglist_appl($c.stf.getObjectValue(cmb_ISUR_CD2), txb_SearchIsuCd2.getValue());
    scwin.fn_list_chglist_sync();
};
scwin.dts_Qty_ApplDtl_OnLoadError = function() {
    $c.stf.alert_error(dts_Qty_ApplDtl);
};
scwin.dts_Qty_IsurDtl_OnLoadError = function() {
    $c.stf.alert_error(dts_Qty_IsurDtl);
};
scwin.dts_Qty_ApplDtl_OnLoadCompleted = function(rowcount) {
    //FillGridHeaderTotalCnt(rowcount, panel_page);
    //CloseWin(rowcount, grd_Qty_ApplDtl); 
    scwin.vTotalCountGrid1 = dts_Qty_ApplDtl.getTotalRow();
};
scwin.dts_Qty_IsurDtl_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    //CloseWin(rowcount, grd_Qty_IsurDtl); 
    scwin.vTotalCountGrid2 = dts_Qty_IsurDtl.getTotalRow();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", procJob));
};
scwin.gform_onload = function() {
    MaxTab_01.setSelectedTabIndex("1");
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.cm.PanelToGroupBox(panel_Top2);

    //init set common code
    scwin.fn_set_code();

    //수량변경,종목명변경 접수(신청) 내역 조회
    //처음 화면 로딩시에는 수량변경의 신청내역(중도상환)만 조회한다.
    scwin.fn_list_qty_appl("", "");
};
scwin.btn_New_onclick = function() {
    // 신규 버튼 클릭

    //수량변경
    if (MaxTab_01.getSelectedTabIndex() == "1") {
        //수량변경 - 발행 및 상장내역 신규 화면 오픈
        if ($c.stf.getObjectValue(txb_SearchIsuCd) == "") {
            $c.win.alert("[종목]을 선택하세요.");
        } else {
            scwin.fn_PopQtyIsur("N", -1, ""); //-1은 의미 없음

        }

        //종목명변경

    } else {
        //종목명변경 - 종목명변경 상장내역 신규 화면 오픈
        if ($c.stf.getObjectValue(txb_SearchIsuCd2) == "") {
            $c.win.alert("[종목]을 선택하세요.");
        } else {
            scwin.fn_PopIsuNmChg("N", -1, ""); //-1은 의미 없음

        }
    }
};
scwin.btn_Close_onclick = async function() {
    //(수량변경) 닫기
    await $c.frame.CloseFrame();
};
scwin.img_SearchIsu_onclick = function() {
    //(수량변경)종목코드 조회
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;

    //팝업
    //fn_PopFindIsuAll(fr_SecuGrpId);		// jackal_11.05.12
    $c.lce.fn_PopFindEtnIsuAll(scwin.fr_SecuGrpId);
    $c.lce.fn_CloseNoData();
    //재조회
    scwin.fn_list_qty_appl($c.stf.getObjectValue(cmb_ISUR_CD), $c.stf.getObjectValue(txb_SearchIsuCd));
    scwin.fn_list_sync();
};
scwin.img_SearchIsu2_onclick = function() {
    //(종목명변경)종목코드 조회
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;

    //fn_PopFindIsuAll(fr_SecuGrpId);		// jackal_11.05.12
    $c.lce.fn_PopFindEtnIsuAll(scwin.fr_SecuGrpId);
    $c.lce.fn_CloseNoData();
    //재조회
    scwin.fn_list_chglist_appl($c.stf.getObjectValue(cmb_ISUR_CD2), $c.stf.getObjectValue(txb_SearchIsuCd2));
    scwin.fn_list_chglist_sync();
};
scwin.btn_Excel_onclick = function() {
    //Save to Excel (수량변경)
    var isExcelDown = false;
    var xls_path;
    var countAppl = 0;
    var countIsur = 0;
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    //파일형식 today_화면명.xls
    var xls_path = $c.session.getExcelDownPath() + today + "_변경상장_STF08021.xls";
    if (MaxTab_01.getSelectedTabIndex() == "1") {
        countAppl = dts_Qty_ApplDtl.getTotalRow();
        countIsur = dts_Qty_IsurDtl.getTotalRow();
        //28은 파일저장 대화창 나타내고, 40은 xls_path에 옵션으로 sheet를 붙이는 의미인 것 같음
        if (countAppl > 0 && countIsur > 0) {
            $c.data.saveExcel(grd_Qty_IsurDtl, "수량변경 발행및상장내역", false, false, false, xls_path);
            $c.data.downloadGridViewExcel(grd_Qty_ApplDtl, "수량변경 신청내역", xls_path, 40);
        } else if (countAppl > 0 && countIsur == 0) {
            $c.data.downloadGridViewExcel(grd_Qty_ApplDtl, "수량변경 신청내역", "", 8);
        } else if (countAppl == 0 && countIsur > 0) {
            $c.data.downloadGridViewExcel(grd_Qty_IsurDtl, "수량변경 발행및상장내역", "", 8);
        } else {
            $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
        }
    } else {
        countAppl = dts_Itm_ApplDtl.getTotalRow();
        countIsur = dts_Itm_IsurDtl.getTotalRow();

        //28은 파일저장 대화창 나타내고, 40은 xls_path에 옵션으로 sheet를 붙이는 의미인 것 같음
        if (countAppl > 0 && countIsur > 0) {
            $c.data.saveExcel(grd_Itm_ListDtl, "변경 상장내역", false, false, false, xls_path);
            $c.data.downloadGridViewExcel(grd_Itm_ApplDtl, "병경 신청내역", xls_path, 40);
        } else if (countAppl > 0 && countIsur == 0) {
            $c.data.downloadGridViewExcel(grd_Itm_ApplDtl, "변경 신청내역", "", 8);
        } else if (countAppl == 0 && countIsur > 0) {
            $c.data.downloadGridViewExcel(grd_Itm_ListDtl, "변경 상장내역", "", 8);
        } else {
            $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
        }
    }
};
