scwin.grd_Qty_ApplDtl_OnClick = function(row, colid) {
    //수량변경 > 발행 및 상장내역 조회
    scwin.v_QtyApplRowClicked = true;
    $c.stf.setObjectValue(cmb_ISUR_CD, dts_Qty_ApplDtl.getCellData(row, "ISUR_CD"));
    $c.stf.setObjectValue(txb_SearchIsuCd, dts_Qty_ApplDtl.getCellData(row, "ISU_CD"));
    $c.stf.setObjectValue(txb_SearchIsuNm, dts_Qty_ApplDtl.getCellData(row, "ISU_ABBRV"));

    //조회
    scwin.fn_list_sync();
};
